import{_ as n,a0 as p,w as d,s as o,I as s,x as e,a1 as t,A as l,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const z=JSON.parse('{"title":"zip 命令的解释与示例 | LCTT x X-CMD","titleTemplate":false,"description":"zip 命令的解释与示例 | LCTT (202302) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"zip 命令的解释与示例 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"zip 命令的解释与示例 | LCTT (202302) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202302/20230117.0 ⭐️⭐️ Learn zip Command in Linux Using Examples","title":"zip 命令的解释与示例","tag":"202302","desc":""},"relativePath":"202302/20230117.0 ⭐️⭐️ Learn zip Command in Linux Using Examples.md","filePath":"[post].md"}'),h={name:"202302/20230117.0 ⭐️⭐️ Learn zip Command in Linux Using Examples.md"};function g(u,i,c,k,b,f){const a=p("Link");return d(),o("div",null,[i[21]||(i[21]=s("h1",{id:"zip-命令的解释与示例",tabindex:"-1"},[e("zip 命令的解释与示例 "),s("a",{class:"header-anchor",href:"#zip-命令的解释与示例","aria-label":"Permalink to “zip 命令的解释与示例”"},"​")],-1)),i[22]||(i[22]=s("blockquote",null,[s("p",null,"这是一份关于理解 Linux 中的 zip 命令的初学者指南，并附有一些例子。")],-1)),i[23]||(i[23]=s("p",null,[s("img",{src:"https://www.debugpoint.com/wp-content/uploads/2023/01/zip-file-head.jpg",alt:""})],-1)),s("p",null,[i[1]||(i[1]=e("这篇文章是 ",-1)),t(a,{href:"https://www.debugpoint.com/category/linux-commands"},{default:l(()=>[...i[0]||(i[0]=[e("Linux 命令",-1)])]),_:1}),i[2]||(i[2]=e("学习系列的一部分。",-1))]),i[24]||(i[24]=r(`<p>zip 文件是一个包含一个或多个文件的压缩档案。它作为一种无损数据压缩技术被广泛使用。由于压缩，它占用的磁盘空间更少，在计算机网络上传输时需要的数据也更少。</p><p>这些压缩文件可以在 Linux、Windows 和 macOS 中轻松提取。有各种支持压缩 zip 文件的软件，也提供提取它们的功能。</p><p>由于它很流行，几乎所有的操作系统都内置了这个功能。</p><p>在本教程中，我们将谈论几种基于终端的方法来压缩 Linux 中的文件。</p><h3 id="linux-中的-zip-命令示例" tabindex="-1">Linux 中的 Zip 命令示例 <a class="header-anchor" href="#linux-中的-zip-命令示例" aria-label="Permalink to “Linux 中的 Zip 命令示例”">​</a></h3><h4 id="语法" tabindex="-1">语法 <a class="header-anchor" href="#语法" aria-label="Permalink to “语法”">​</a></h4><p>在 Linux 中，你需要使用的压缩文件的程序名称是 <code>zip</code>。下面是基本的语法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>zip [压缩文件名] file1 file2 file3</span></span></code></pre></div><p>以下是正式的语法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>zip [-options] [-b path] [-t mmddyyyy] [-n suffixes] [zipfile list] [-xi list]</span></span></code></pre></div><p>理想情况下，<code>zip</code> 命令应该被安装在所有主流的 Linux 发行版中。如果没有，使用下面的命令来安装它。</p><h4 id="在-debian、ubuntu-和相关发行版上安装" tabindex="-1">在 Debian、Ubuntu 和相关发行版上安装 <a class="header-anchor" href="#在-debian、ubuntu-和相关发行版上安装" aria-label="Permalink to “在 Debian、Ubuntu 和相关发行版上安装”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install zip</span></span></code></pre></div><h4 id="在-fedora、基于-rhel-的系统上安装" tabindex="-1">在 Fedora、基于 RHEL 的系统上安装 <a class="header-anchor" href="#在-fedora、基于-rhel-的系统上安装" aria-label="Permalink to “在 Fedora、基于 RHEL 的系统上安装”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install zip</span></span></code></pre></div><h4 id="在-arch-linux-上安装" tabindex="-1">在 Arch Linux 上安装 <a class="header-anchor" href="#在-arch-linux-上安装" aria-label="Permalink to “在 Arch Linux 上安装”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pacman -S zip</span></span></code></pre></div><p>让我们继续看一些例子。</p><h4 id="如何压缩文件和文件夹" tabindex="-1">如何压缩文件和文件夹 <a class="header-anchor" href="#如何压缩文件和文件夹" aria-label="Permalink to “如何压缩文件和文件夹”">​</a></h4><p>我的测试目录中有以下三个文件。它们是 <code>file1.txt</code>、<code>file2.txt</code> 和 <code>file3.txt</code>。如果我想用 zip 压缩三个文件，并创建一个 <code>myfiles.zip</code> 的压缩包，用下面的命令就可以了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>zip myfiles.zip file1.txt file2.txt file3.mp3</span></span></code></pre></div><p>输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>adding: file1.txt (stored 0%)</span></span>
<span class="line"><span>adding: file2.txt (stored 0%)</span></span>
<span class="line"><span>adding: file3.mp3 (deflated 13%)</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/01/Output-of-Basic-zip-command-in-Linux.jpg" alt="Linux 中基本压缩命令的输出"></p><p>这里你应该记住几个要点。</p><ul><li>当创建一个 zip 文件时，你应该有对当前目录的修改权限。</li><li>zip 文件格式不包含权限，即读（4）、写（2），和执行（1）。所以，创建该文件的用户成为该文件的所有者。</li><li>如果你想使用带有权限的 zip，可以尝试使用 <code>tar</code> 命令（将在后面的教程中解释）。</li><li>在上面的输出中，<code>zip</code> 命令显示了被添加到存档中的文件名和压缩方法。</li><li>在目标文件名中指定 .zip 文件名的扩展名并不是必须的。如果你省略了 .zip，<code>zip</code> 会在最后加上 .zip。</li></ul><p>当你操作成百上千的文件时，为了减少终端中的输出，你可以使用 <code>-q</code> 参数来抑制 <code>zip</code> 命令中的输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>zip -q myfiles.zip file1.txt file2.txt file3.txt</span></span></code></pre></div><h4 id="递归压缩子文件夹" tabindex="-1">递归压缩子文件夹 <a class="header-anchor" href="#递归压缩子文件夹" aria-label="Permalink to “递归压缩子文件夹”">​</a></h4><p><code>zip</code> 命令的 <code>-r</code> 选项使你能够囊括所有子目录。这个选项会递归地遍历到一个目录结构的最后一个子目录，并将它们全部加入到压缩文件中。</p><p>下面的命令创建了一个包含 <code>my_folder</code> 内所有内容和子目录的压缩文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>zip -r myfolder.zip my_folder</span></span></code></pre></div><p>你也可以使用通配符（<code>*</code>）在你的压缩文件中包含特定类型的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>zip -0 my_movies.zip *.mp4</span></span></code></pre></div><h4 id="混合添加文件和目录到压缩文件" tabindex="-1">混合添加文件和目录到压缩文件 <a class="header-anchor" href="#混合添加文件和目录到压缩文件" aria-label="Permalink to “混合添加文件和目录到压缩文件”">​</a></h4><p>有了以上所有的选项，<code>zip</code> 命令允许你把文件和目录一起作为参数指定。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>zip -r myfiles.zip file1.txt file2.txt file3.txt my_folder1 my_folder2</span></span></code></pre></div><h3 id="压缩算法" tabindex="-1">压缩算法 <a class="header-anchor" href="#压缩算法" aria-label="Permalink to “压缩算法”">​</a></h3><p>zip 压缩的默认输出包含两个不同的词，即 <code>deflate</code> 和 <code>store</code>。zip 默认使用的压缩方法是 <code>deflate</code>。如果它成功地压缩了文件，那么输出显示 <code>deflate</code>。而当它不能压缩一个文件时，它只是将它们原封不动地存储在 .zip 文件中。这些文件的输出显示为 <code>store</code>。</p><p>目前有许多压缩算法。其中一种是 bzip2 压缩法，在 Linux 中的 <code>zip</code> 命令支持它。你可以指定压缩算法作为一个命令选项来使用。使用选项 <code>-Z</code>，后面跟上算法名称，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>zip -r -Z bzip2 myfolder.zip my_folder</span></span></code></pre></div><h4 id="压缩级别" tabindex="-1">压缩级别 <a class="header-anchor" href="#压缩级别" aria-label="Permalink to “压缩级别”">​</a></h4><p><code>zip</code> 命令还允许你指定压缩级别。压缩级别是指你想让 zip 优化多少来减少包的大小。它是一个从 0 到 9 的数值范围。压缩级别为 9 的值是最高的压缩。默认值是 6。</p><p>记住，如果你用 zip 压缩成千上万个大小不一的文件，它可能会占用较多的系统资源，并花费大量的时间。所以，如果你在程序中使用它，或者用 shell 脚本处理大量的文件，请遵循正确的编程标准。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>zip -9 -r myfolder.zip my_folder</span></span></code></pre></div><h4 id="用密码保护一个压缩文件" tabindex="-1">用密码保护一个压缩文件 <a class="header-anchor" href="#用密码保护一个压缩文件" aria-label="Permalink to “用密码保护一个压缩文件”">​</a></h4><p>你也可以用下面的 <code>-e</code> 选项对压缩文件进行密码保护：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>zip -e -r myfolder.zip my_folder</span></span></code></pre></div><p>运行该命令后，它将要求输入密码。</p><blockquote><p>注意。尽量不要使用 zip 命令来对压缩文件进行密码保护。zip 的加密算法是使用流式加密的 PKZIP。而它很容易被破解。如果你想保护你的文件，请使用 7-Zip 或其他高级工具。</p></blockquote><h4 id="分割较大的压缩文件" tabindex="-1">分割较大的压缩文件 <a class="header-anchor" href="#分割较大的压缩文件" aria-label="Permalink to “分割较大的压缩文件”">​</a></h4><p>许多应用程序、服务器和文件共享可能包含固定大小的文件上传限制。例如，你有一个 10GB 的文件，但服务只允许每个文件 1GB。使用 <code>zip</code> 的 <code>-s</code> 选项，你可以将其压缩并分割成几块进行上传。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>zip -s 1g -r myfolder.zip my_folder</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>你学到了一些 <code>zip</code> 命令的基本知识。它对大多数本地情况很有用，在这些情况下，你需要通过即时压缩来进行快速备份。然而，对于更高级的选项，你应该使用 7-Zip 或其他命令，我将在接下来的几篇文章中分享。</p>`,55)),s("p",null,[i[4]||(i[4]=e("同时，你可以在 ",-1)),t(a,{href:"https://linux.die.net/man/1/zip"},{default:l(()=>[...i[3]||(i[3]=[e("zip 手册",-1)])]),_:1}),i[5]||(i[5]=e(" 中了解更多。",-1))]),i[25]||(i[25]=s("hr",null,null,-1)),s("p",null,[i[7]||(i[7]=e("via: ",-1)),t(a,{href:"https://www.debugpoint.com/zip-command-linux-examples/"},{default:l(()=>[...i[6]||(i[6]=[e("https://www.debugpoint.com/zip-command-linux-examples/",-1)])]),_:1})]),s("p",null,[i[12]||(i[12]=e("作者：",-1)),t(a,{href:"https://www.debugpoint.com/author/admin1/"},{default:l(()=>[...i[8]||(i[8]=[e("Arindam",-1)])]),_:1}),i[13]||(i[13]=e(" 选题：",-1)),t(a,{href:"https://github.com/lkxed"},{default:l(()=>[...i[9]||(i[9]=[e("lkxed",-1)])]),_:1}),i[14]||(i[14]=e(" 译者：",-1)),t(a,{href:"https://github.com/Chao-zhi"},{default:l(()=>[...i[10]||(i[10]=[e("Chao-zhi",-1)])]),_:1}),i[15]||(i[15]=e(" 校对：",-1)),t(a,{href:"https://github.com/wxy"},{default:l(()=>[...i[11]||(i[11]=[e("wxy",-1)])]),_:1})]),s("p",null,[i[18]||(i[18]=e("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...i[16]||(i[16]=[e("LCTT",-1)])]),_:1}),i[19]||(i[19]=e(" 原创编译，",-1)),t(a,{href:"https://linux.cn/"},{default:l(()=>[...i[17]||(i[17]=[e("Linux中国",-1)])]),_:1}),i[20]||(i[20]=e(" 荣誉推出",-1))])])}const y=n(h,[["render",g]]);export{z as __pageData,y as default};
